const icons={check:'<path d="m5 12 4 4 10-10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',brain:'<path d="M12 4a4 4 0 0 0-7-1 4 4 0 0 0-2 7 5 5 0 0 0 2 9 4 4 0 0 0 7 1V4Zm0 0a4 4 0 0 1 7-1 4 4 0 0 1 2 7 5 5 0 0 1-2 9 4 4 0 0 1-7 1M7 7l2 2m8-2-2 2M6 14l3-1m9 1-3-1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',qr:'<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h3v3h-3zM21 15v6h-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4 0 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0" transform="translate(1 -1)"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',refresh:'<path d="M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6M4 17a9 9 0 0 0 15 2l3-3m0 6v-6h-6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='humanproof-demo-v2';
let db, screen='overview', role='author', gateIndex=0, verifyId=null, verifyResult=null, busy=false;
const gateNames=['Teach-back','Fault Injection','What-if'];
const gateTitles=['선택 이유를 자신의 말로 설명하기','복제 문단에 숨은 오류 찾기','조건이 달라지면 영향 설명하기'];
const gatePrompts=['파일 버전 ID와 SHA-256을 함께 기록하는 이유는 무엇인가요? 각각이 무엇을 확인하는지 설명해 주세요.','아래는 오류를 넣은 검증용 복제 문단입니다. 잘못된 설명을 찾고, 수정 방향과 그 이유를 적어 주세요.','승인자가 1명에서 2명으로 늘어난다면, 데이터 구조와 승인 상태 처리에 어떤 변화가 필요한가요?'];
const samples=[
 '버전 ID는 작업 안에서 승인 대상을 식별하고, SHA-256은 승인 시점의 파일 바이트가 전달된 파일과 같은지 확인합니다. v1을 승인한 뒤 파일이 바뀌면 새 v2를 만들어야 합니다. v1의 승인을 v2에 자동으로 적용하면 승인하지 않은 내용까지 승인된 것으로 오해할 수 있습니다.',
 '오류는 “파일 이름이 같으면 내용이 변경되어도 기존 승인이 유지된다”는 부분입니다. 파일명은 내용을 식별하지 못합니다. 새 파일의 SHA-256을 계산해 새 버전으로 등록하고 재검토해야 합니다. 기존 승인 기록은 v1에만 연결하고 v2는 미승인으로 표시합니다.',
 '버전별 승인자 기록을 여러 개 저장하도록 관계를 변경하고, 서로 다른 두 검토자의 승인이 모였는지 확인해야 합니다. 첫 승인 뒤에는 승인 대기 상태를 유지하고, 두 번째 승인 뒤에 최종 증명서를 발급합니다. 자기 승인과 중복 승인을 차단하고, 두 승인자의 시각과 대상 버전을 기록해야 합니다.'
];
const rubric=['버전 ID와 파일 해시의 역할 구분 · 변경 시 재승인 필요성','파일명 비교의 오류 발견 · 해시 비교와 새 버전 등록 제안','복수 승인 기록 구조 · 두 승인 완료 전까지 대기 상태 유지'];
const riskLabels=['AI 사용 비중','결과의 중요도','검증 근거 부족','과거 과제 실패'];
const riskMax=[3,3,2,2];
const checks=['문서의 주요 주장과 근거를 확인했습니다','AI 사용 범위와 인간 기여를 확인했습니다','이해 과제의 답변과 평가 근거를 확인했습니다','승인할 PDF의 버전 ID와 해시를 확인했습니다'];
const stamp=t=>new Intl.DateTimeFormat('ko-KR',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Seoul'}).format(new Date(t));
const fmtSize=n=>n<1024*1024?(n/1024).toFixed(1)+' KB':(n/1024/1024).toFixed(1)+' MB';
const uid=p=>p+'-'+crypto.randomUUID();
const to64=bytes=>{let t='';for(let i=0;i<bytes.length;i+=8192)t+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(t)};
const from64=t=>Uint8Array.from(atob(t),c=>c.charCodeAt(0));
const hash=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');
const hashText=t=>hash(new TextEncoder().encode(t));
const canonical=o=>JSON.stringify(o,(key,value)=>value&&typeof value==='object'&&!Array.isArray(value)?Object.fromEntries(Object.keys(value).sort().map(k=>[k,value[k]])):value);
const current=()=>db.versions[db.versions.length-1];
const approvalFor=v=>db.approvals.find(a=>a.versionId===v.id);
const totalScore=v=>v.gates.reduce((s,g)=>s+(g.evaluation?.score??0),0);
const gatesSubmitted=v=>v.gates.every(g=>g.submitted);
const gatesPassed=v=>gatesSubmitted(v)&&v.gates.every(g=>g.evaluation&&g.evaluation.reason.trim()&&!g.evaluation.critical)&&totalScore(v)>=5;
const statusOf=v=>{const a=approvalFor(v);if(a?.revokedAt)return ['승인 철회','red'];if(a)return ['승인 완료','green'];if(v.gates.some(g=>g.evaluation?.critical)||v.returned)return ['수정 요청','orange'];if(gatesPassed(v))return ['검토 완료','purple'];if(gatesSubmitted(v))return ['검토 대기','purple'];return ['이해 과제 대기','purple']};
const badge=v=>{const [text,color]=statusOf(v);return `<span class="badge ${color}">${text}</span>`};
function makePdf(){
 const lines=['HUMANPROOF / SYSTEM DESIGN','AI-assisted work and human approval','1. AI produced the design draft.','2. The author explains design choices.','3. A different reviewer evaluates the answers.','4. Approval is bound to one immutable version.','5. SHA-256 compares the delivered file bytes.','6. A changed file requires a new version.','7. Revocation is separate from file integrity.','Sample document for a presentation prototype.'];
 const stream='BT /F1 18 Tf 48 770 Td ('+lines[0]+') Tj /F1 11 Tf '+lines.slice(1).map(t=>'0 -32 Td ('+t+') Tj').join(' ')+' ET';
 const objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream'];
 let text='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(text.length);text+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});const xref=text.length;text+='xref\n0 6\n0000000000 65535 f \n'+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF\n';return new TextEncoder().encode(text);
}
function blankGates(){return gateNames.map(()=>({answer:'',confidence:80,submitted:false,evaluation:null}))}
async function makeVersion(n,name,bytes,tool,scope,risk,reason){return{id:uid('ver'),n,fileName:name,size:bytes.length,fileData:to64(bytes),hash:await hash(bytes),tool,scope,risk,gates:blankGates(),checks:checks.map(()=>false),memo:'',reason,createdAt:new Date().toISOString(),returned:false}}
async function seed(){
 const bytes=makePdf();db={schema:2,workId:uid('work'),title:'AI 작업 승인 시스템 설계 보고서',versions:[await makeVersion(1,'system_design_v1.pdf',bytes,'ChatGPT','설계 초안 생성 및 요구사항 정리',[3,3,1,1],'최초 파일 등록')],approvals:[],events:[]};
 await audit('작업 · PDF v1 등록','작성자 A','AI 활용 초안과 검토 대상 파일을 등록했습니다.');
 await audit('인간 기여 기록','작성자 A','요구사항을 직접 정리하고 승인 범위와 버전 변경 규칙을 보완했습니다.');save();
}
async function audit(action,actor,note,target=current().id){const body={id:uid('evt'),action,actor,note,target,time:new Date().toISOString()};const prev=db.events.at(-1)?.eventHash||'0'.repeat(64);db.events.push({...body,prevHash:prev,eventHash:await hashText(prev+canonical(body))})}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(db))}catch{toast('저장 공간이 부족합니다. 현재 화면에서는 계속 시연할 수 있습니다.')}}
let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3700)}
function download(data,name,type='application/pdf'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function baseShell(content){const v=current();return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">${icon('shield')}</span><div>HumanProof<small>HUMAN APPROVAL</small></div></div><div><div class="side-label">WORKSPACE</div><nav class="nav" aria-label="작업 메뉴">${[['overview','grid','작업 관리'],['gate','brain','이해 과제'],['review','shield','검토 · 승인'],['certificate','file','승인 증명서'],['history','clock','버전 · 이력']].map(([s,i,t])=>`<button data-nav="${s}" class="${screen===s?'active':''}" ${screen===s?'aria-current="page"':''}>${icon(i)}${t}${s==='overview'?'<span class="count">1</span>':''}</button>`).join('')}</nav></div><div class="team-box"><b>소프트웨어공학 프로젝트</b>경희대학교 · 2026학년도<div class="small muted">발표용 워크스페이스</div></div></aside><div><header class="topbar"><div class="crumb">워크스페이스 <b>/ ${esc({overview:'작업 관리',gate:'이해 과제',review:'검토 · 승인',certificate:'승인 증명서',history:'버전 · 이력'}[screen])}</b></div><div class="mobile-brand"><span class="mark">${icon('shield')}</span>HumanProof</div><div class="top-actions"><span class="demo-pill">발표용 프로토타입</span><div class="role-control"><span class="avatar">${role==='author'?'A':'B'}</span><select id="role" aria-label="시연 역할"><option value="author" ${role==='author'?'selected':''}>작성자 A</option><option value="reviewer" ${role==='reviewer'?'selected':''}>검토자 B</option></select></div></div></header><main class="main">${content}<div class="footer-note"><strong>발표용 데모</strong> · 역할과 기록은 이 브라우저에서 체험합니다. 계정 인증·서버 보관·전자서명은 연결되지 않았습니다.<br>검토 절차의 기록이며 실제 이해, 문서의 정확성 또는 AI 신고의 진실성을 보증하지 않습니다.</div></main></div></div>`}
function heading(t,d,actions=''){return `<div class="page-heading"><div><h1>${t}</h1><p>${d}</p></div>${actions}</div>`}
function steps(){const v=current(),a=approvalFor(v);let at=a&&!a.revokedAt?3:gatesSubmitted(v)?2:1;return `<div class="steps">${['작업 등록','이해 과제','검토 · 승인','파일 검증'].map((t,i)=>`<div class="step ${i<at?'done':i===at?'current':''}"><span>${i<at?'✓':i+1}</span>${t}</div>`).join('')}</div>`}
function fileHead(v=current()){return `<div class="work-row"><div class="pdf-icon">PDF</div><div style="flex:1;min-width:0"><div class="work-title">${esc(db.title)}</div><div class="flex wrap"><span class="badge">v${v.n}</span><span class="small muted">작성자 A · 검토자 B</span></div></div>${badge(v)}</div>`}
function guide(){return `<section class="guide"><div class="eyebrow">PRESENTATION DEMO</div><h2>5분 시연 가이드</h2><p>한 작업의 검토·승인 흐름을 체험하세요.</p><div class="guide-list">${[['등록','PDF와 AI 사용 범위 확인'],['이해 확인','3종 과제에 답변 제출'],['인간 승인','검토자로 전환해 평가 · 승인'],['파일 검증','원본 일치와 변경 파일 비교']].map(([t,d],i)=>`<div class="guide-item"><span>${i+1}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</div><button class="btn" data-action="reset">${icon('refresh')}시연 처음부터</button><p class="small">샘플 답변 · 평가 버튼으로 빠르게 진행할 수 있습니다.</p></section>`}
function riskPanel(){const r=current().risk,total=r.reduce((a,b)=>a+b,0),level=total>=7?'높음':total>=4?'보통':'낮음';return `<section class="panel risk-panel"><div class="panel-body"><div class="eyebrow">KNOWLEDGE DEBT RISK</div><div class="flex between"><h3>검토 위험도</h3><span class="badge ${total>=7?'orange':total>=4?'purple':'green'}">${level}</span></div><div class="risk-score mt">${total} <small>/ 10</small></div><div class="risk-track"><div style="width:${total*10}%"></div></div><div class="risk-grid">${riskLabels.map((t,i)=>`<span class="muted">${t}</span><b>${r[i]} / ${riskMax[i]}</b>`).join('')}</div><p class="inline-note">규칙 v1.0 · 작성자 입력 기준<br>시연에서는 세 종류의 과제를 모두 확인합니다.</p></div></section>`}
function overview(){const v=current(),a=approvalFor(v);return heading('작업 관리','AI 작업과 인간의 검토 기록을 한 버전에 연결합니다.',`<button class="btn primary" data-action="newWork">${icon('plus')}새 작업 등록</button>`)+`<div class="metrics">${[['등록된 작업','1','file'],['검토 진행 중',a&&!a.revokedAt?'0':'1','clock'],['승인 완료',a&&!a.revokedAt?'1':'0','shield']].map(([t,n,i])=>`<div class="metric"><div><div class="label">${t}</div><div class="number">${n}<small>건</small></div></div><div class="metric-icon">${icon(i)}</div></div>`).join('')}</div><div class="split"><section class="panel"><div class="panel-head"><h2>현재 작업</h2><span class="muted small">${stamp(v.createdAt)}</span></div>${fileHead()}${steps()}<div class="panel-body"><div class="detail-grid"><div class="detail-item"><span class="muted">등록 파일</span>${esc(v.fileName)}<div class="inline-note">${fmtSize(v.size)} <button class="btn ghost small" data-action="downloadOriginal">${icon('download')}원본 받기</button></div></div><div class="detail-item"><span class="muted">승인 대상 버전</span>v${v.n} · ${a&&!a.revokedAt?'인간 승인 완료':'아직 승인되지 않음'}</div><div class="detail-item"><span class="muted">AI 활용 도구</span>${esc(v.tool)}</div><div class="detail-item"><span class="muted">AI 사용 범위 <small>(작성자 신고)</small></span>${esc(v.scope)}</div></div><div class="subsection"><h3>파일 식별 정보</h3><div class="inline-note mono">${esc(v.id)}</div><div class="hash">${icon('link')}<div><div class="muted small" style="margin-bottom:7px">SHA-256</div><div class="mono">${v.hash}</div></div></div></div><div class="callout mt ${a&&!a.revokedAt?'success':''}">${icon(a?'shield':'brain')}<div><b>${a&&!a.revokedAt?'이 버전에 대한 인간 승인이 기록되었습니다':'작성자의 이해를 먼저 확인합니다'}</b>${a&&!a.revokedAt?'수신자는 승인 기록과 파일 일치 여부를 각각 확인할 수 있습니다.':'Teach-back, Fault Injection, What-if 답변을 검토자가 평가합니다.'}</div></div></div><div class="panel-foot"><span class="small muted">${a?'승인 기록은 v'+v.n+'에 고정됩니다.':'자기 승인 금지 · 검토자 B가 승인합니다.'}</span><button class="btn primary" data-nav="${a?'certificate':gatesSubmitted(v)?'review':'gate'}">${a?'승인 증명서 보기':gatesSubmitted(v)?'검토 화면으로':'이해 과제 시작'}</button></div></section><aside class="support-column">${guide()}${riskPanel()}</aside></div>`}
function gateScreen(){const v=current(),g=v.gates[gateIndex],completed=v.gates.filter(g=>g.submitted).length;return heading('이해 과제','답변의 근거를 남기고, 다른 사람이 평가합니다.',`<span class="badge purple">${completed} / 3 제출</span>`)+`<div class="split"><section class="panel">${fileHead()}<div class="gate-tabs" role="tablist" aria-label="이해 과제">${gateNames.map((n,i)=>`<button role="tab" aria-selected="${i===gateIndex}" data-gate="${i}" class="${i===gateIndex?'active':''}">${n}${v.gates[i].submitted?' ✓':''}</button>`).join('')}</div><div class="panel-body"><div class="flex between"><div class="eyebrow">GATE ${String(gateIndex+1).padStart(2,'0')}</div><span class="small muted">${g.submitted?'제출 완료 · 답변 고정':'작성자 A에게 배정'}</span></div><h2>${gateTitles[gateIndex]}</h2><div class="task-prompt"><span class="badge">질문</span><p>${gatePrompts[gateIndex]}</p>${gateIndex===1?'<div class="reference">“승인 여부는 파일 이름으로 확인한다. 파일 이름이 같으면 내용이 변경되어도 기존 승인이 유지된다.”</div><p class="small muted">오류는 검증용 복제 문단에만 넣었습니다. 원본 PDF는 바뀌지 않습니다.</p>':''}</div><form id="gateForm"><label class="field"><span>나의 답변</span><textarea id="answer" required placeholder="내가 이해한 내용을 근거와 함께 적어 주세요." ${g.submitted||role!=='author'?'readonly':''}>${esc(g.answer)}</textarea></label><div class="field"><label for="confidence">답변에 대한 자기 확신</label><div class="confidence"><input id="confidence" type="range" min="0" max="100" step="5" value="${g.confidence}" ${g.submitted||role!=='author'?'disabled':''}><b id="confidenceValue">${g.confidence}%</b></div><p class="inline-note">확신도는 검토 참고 자료이며 합격 점수와 별도로 기록합니다.</p></div>${g.evaluation?`<div class="callout ${g.evaluation.critical?'error':'success'}">${icon('info')}<div><b>검토자 평가 · ${g.evaluation.score} / 2점</b>${esc(g.evaluation.reason)}${g.evaluation.critical?'<br>치명 오류가 있어 수정이 필요합니다.':''}</div></div>`:''}<div class="error-text" id="gateError"></div><div class="flex between wrap mt"><button type="button" class="btn small" data-action="sampleAnswer" ${g.submitted||role!=='author'?'disabled':''}>샘플 답변 넣기</button><button class="btn primary" type="submit" ${g.submitted||role!=='author'?'disabled':''}>${g.submitted?'답변 제출 완료':'답변 제출'}</button></div>${role!=='author'?'<p class="inline-note">답변을 작성하려면 상단에서 작성자 A로 전환하세요.</p>':''}</form></div><div class="panel-foot"><span class="small muted">임시 답변은 이 브라우저에 저장됩니다.</span><button class="btn ${completed===3?'primary':''}" data-nav="review" ${completed!==3?'disabled':''}>검토 · 승인으로</button></div></section><aside class="support-column"><section class="guide"><div class="eyebrow">UNDERSTANDING GATE</div><h2>근거를 남기는 이해 확인</h2><p>체크만으로 끝내지 않고, 설명과 오류 식별을 기록합니다.</p><div class="guide-list">${gateNames.map((n,i)=>`<div class="guide-item"><span>${v.gates[i].submitted?'✓':i+1}</span><div><b>${n}</b><p>${v.gates[i].submitted?'답변 제출 완료':'아직 제출하지 않음'}</p></div></div>`).join('')}</div><div class="mini-progress">${v.gates.map(g=>`<div class="${g.submitted?'done':''}"></div>`).join('')}</div><button class="btn mt" data-action="sampleAll" ${role!=='author'||completed===3?'disabled':''}>3개 샘플 답변 채우기</button><p class="small">샘플을 채운 뒤 각 과제의 답변 제출 버튼을 누르세요.</p></section>${riskPanel()}</aside></div>`}
function approvalReasons(v){const reasons=[];if(role!=='reviewer')reasons.push('검토자 B 역할로 전환해야 합니다. 자기 승인은 금지됩니다.');if(!gatesSubmitted(v))reasons.push('세 과제의 답변을 모두 제출해야 합니다.');if(!v.gates.every(g=>g.evaluation?.reason.trim()))reasons.push('모든 과제에 점수와 평가 근거가 필요합니다.');if(totalScore(v)<5)reasons.push('총점 5 / 6점 이상이 필요합니다.');if(v.gates.some(g=>g.evaluation?.critical))reasons.push('치명 오류가 있는 과제의 재검토가 필요합니다.');if(!v.checks.every(Boolean))reasons.push('필수 체크리스트 4개를 모두 확인해야 합니다.');if(!v.memo.trim())reasons.push('최종 검토 근거를 입력해야 합니다.');if(approvalFor(v))reasons.push('이미 승인 기록이 있는 버전입니다. 새 버전을 등록해 주세요.');if(v.returned)reasons.push('수정 요청 후 답변을 다시 제출해야 합니다.');return reasons}
function reviewScreen(){const v=current(),reasons=approvalReasons(v),passed=gatesPassed(v);return heading('검토 · 승인','검토자 B가 답변과 최종 파일을 확인합니다.',`<button class="btn small" data-action="sampleEvaluation" ${role!=='reviewer'||!gatesSubmitted(v)||!!approvalFor(v)?'disabled':''}>샘플 평가 채우기</button>`)+`<div class="split"><section class="panel">${fileHead()}<div class="panel-body">${role!=='reviewer'?`<div class="callout warning gap">${icon('info')}<div><b>자기 승인은 할 수 없습니다</b>상단에서 검토자 B로 전환해 평가와 승인을 진행하세요.</div></div>`:''}${!gatesSubmitted(v)?`<div class="callout warning gap">${icon('brain')}<div><b>아직 답변이 모두 제출되지 않았습니다</b>이해 과제 화면에서 세 답변을 제출해 주세요.</div></div>`:''}<div class="gate-result"><div><b>이해 과제 판정</b><p class="small muted">총점 70% 이상 · 치명 오류 없음 · 검토 근거 필수</p></div><div class="text-right"><div class="score">${totalScore(v)} <span class="small muted">/ 6</span></div><span class="badge ${passed?'green':'orange'}">${passed?'평가 규칙 통과':'평가 진행 중'}</span></div></div>${gateNames.map((n,i)=>{const g=v.gates[i],e=g.evaluation;return `<div class="eval-card"><div class="flex between"><h3>${n}</h3><span class="small muted">자기 확신 ${g.confidence}%</span></div><div class="answer-quote">${g.submitted?esc(g.answer):'답변이 제출되지 않았습니다.'}</div><p class="inline-note">평가 기준: ${rubric[i]}</p><div class="eval-row"><label class="field"><span>점수</span><select data-eval-score="${i}" ${role!=='reviewer'||!g.submitted||approvalFor(v)?'disabled':''}><option value="" ${!e?'selected':''}>평가 전</option>${[0,1,2].map(s=>`<option value="${s}" ${e&&e.score===s?'selected':''}>${s}점 · ${['미충족','부분 충족','충족'][s]}</option>`).join('')}</select></label><label class="field"><span>평가 근거</span><textarea data-eval-reason="${i}" placeholder="어떤 답변에서 기준 충족 여부를 확인했나요?" ${role!=='reviewer'||!g.submitted||approvalFor(v)?'readonly':''}>${esc(e?.reason||'')}</textarea></label></div><label class="check-row"><input type="checkbox" data-critical="${i}" ${e?.critical?'checked':''} ${role!=='reviewer'||!g.submitted||approvalFor(v)?'disabled':''}>${i===1?'주입 오류 미발견 또는 치명 오류 있음':'치명적 오개념 있음'}</label></div>`}).join('')}</div></section><aside class="support-column"><section class="panel"><div class="panel-head"><h2>최종 검토 체크리스트</h2>${icon('shield')}</div><div class="panel-body">${checks.map((t,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${v.checks[i]?'checked':''} ${role!=='reviewer'||approvalFor(v)?'disabled':''}>${t}</label>`).join('')}<label class="field"><span>최종 검토 근거</span><textarea id="reviewMemo" placeholder="승인 판단의 근거를 남겨 주세요." ${role!=='reviewer'||approvalFor(v)?'readonly':''}>${esc(v.memo)}</textarea></label><div id="approvalControls">${approvalControls()}</div></div></section><section class="guide"><div class="eyebrow">VERSION-BOUND APPROVAL</div><h2>승인은 v${v.n}에 고정됩니다</h2><p>파일이 변경되면 새 버전으로 등록하고 재검토해야 합니다.</p><button class="btn mt" data-action="downloadOriginal">${icon('download')}최종 PDF 확인</button></section></aside></div>`}
function approvalControls(){const v=current(),reasons=approvalReasons(v),a=approvalFor(v);if(a)return `<div class="callout ${a.revokedAt?'error':'success'}">${icon('shield')}<div><b>${a.revokedAt?'이 승인은 철회되었습니다':'승인 증명서가 발급되었습니다'}</b>이 버전은 다시 승인할 수 없습니다.</div></div><button class="btn primary mt" data-nav="certificate" style="width:100%">증명서 보기</button>`;return `<div class="block-reasons" id="blockReasons">${reasons.length?reasons.map(s=>`<div>· ${s}</div>`).join(''):'승인 조건을 모두 충족했습니다.'}</div><button class="btn primary" data-action="approve" style="width:100%" ${reasons.length?'disabled':''}>${icon('shield')}v${v.n} 승인 · 증명서 발급</button><button class="btn danger mt" data-action="return" style="width:100%" ${role!=='reviewer'||!gatesSubmitted(v)?'disabled':''}>수정 요청</button>`}
function latestApproval(){return db.approvals.at(-1)}
function certScreen(){const a=latestApproval();if(!a)return heading('승인 증명서','검토를 통과하고 승인하면 이곳에서 증명서를 확인할 수 있습니다.')+`<section class="panel empty">${icon('shield')}<h2>아직 발급된 증명서가 없습니다</h2><p>이해 과제를 제출하고 검토자 B의 승인을 받아 주세요.</p><button class="btn primary" data-nav="review">검토 화면으로</button></section>`;const v=db.versions.find(v=>v.id===a.versionId);return heading('승인 증명서','검토 근거와 승인 대상 파일을 연결한 기록입니다.',`<span class="badge ${a.revokedAt?'red':'green'}">${a.revokedAt?'철회된 승인':'승인 기록 발급'}</span>`)+`<article class="receipt"><div class="receipt-top"><div><div class="eyebrow">HUMAN APPROVAL RECEIPT</div><h2>인간 승인 증명서</h2></div>${icon('shield')}</div><div class="receipt-body"><div class="flex between"><span class="badge purple">${esc(a.serial)}</span><span class="muted small">발표용 데모</span></div><div class="receipt-title">${esc(a.title)}</div><div class="receipt-data"><div class="detail-item"><span class="muted">승인 대상</span>PDF v${v.n}<div class="inline-note">${esc(v.fileName)}</div></div><div class="detail-item"><span class="muted">검토 · 승인자</span>검토자 B<div class="inline-note">작성자와 다른 시연 역할</div></div><div class="detail-item"><span class="muted">승인 시각 (한국)</span>${stamp(a.approvedAt)}</div><div class="detail-item"><span class="muted">이해 과제 결과</span>${a.score} / 6점 · 평가 규칙 통과</div></div><h3>승인된 파일의 SHA-256</h3><div class="hash mono">${a.fileHash}</div><p class="inline-note mono">version_id: ${esc(v.id)}</p><div class="subsection"><h3>인간 검토 근거</h3><p style="font-size:.875rem;margin-top:12px">${esc(a.memo)}</p></div>${v.id!==current().id?`<div class="callout warning mt">${icon('info')}<div><b>현재 최신 버전은 v${current().n}입니다</b>이 증명서는 v${v.n}에만 적용됩니다. 최신 버전은 별도 승인이 필요합니다.</div></div>`:''}${a.revokedAt?`<div class="callout error mt">${icon('close')}<div><b>승인 철회 · ${stamp(a.revokedAt)}</b>${esc(a.revocationReason)}</div></div>`:''}<div class="receipt-bottom"><div><h3>QR로 승인 기록 확인</h3><p class="inline-note">승인 상태와 파일 일치 여부를 분리해 확인합니다.<br>다른 기기에서는 발급 당시 요약만 확인할 수 있습니다.</p><button class="btn small mt" data-action="verify" data-id="${a.id}">${icon('qr')}검증 화면 열기</button></div><div id="qrcode" aria-label="시연 승인 검증 링크 QR"></div></div><div class="inline-note">전자서명 미연결 · 증명서 내용 해시 ${a.payloadHash.slice(0,18)}…</div></div></article><div class="receipt-actions"><button class="btn" data-action="downloadReceipt">${icon('download')}증명서 JSON 받기</button><button class="btn" data-action="print">${icon('file')}인쇄 · PDF 저장</button><button class="btn" data-action="newVersion">${icon('plus')}새 버전 등록</button><button class="btn danger" data-action="revoke" ${role!=='reviewer'||a.revokedAt?'disabled':''}>승인 철회</button></div>`}
function publicRecord(a){return {id:a.id,title:a.title,n:a.n,fileName:a.fileName,fileHash:a.fileHash,approvedAt:a.approvedAt,serial:a.serial,revokedAt:a.revokedAt||null,revocationReason:a.revocationReason||''}}
function verifyUrl(a){const base=location.protocol==='file:'?document.querySelector('meta[name=demo-site-url]').content:location.href.split('#')[0];return base+'#verify='+encodeURIComponent(to64(new TextEncoder().encode(JSON.stringify(publicRecord(a)))))}
function parseRecord(){try{const h=location.hash;if(!h.startsWith('#verify='))return null;const r=JSON.parse(new TextDecoder().decode(from64(decodeURIComponent(h.slice(8)))));if(typeof r.id!=='string'||typeof r.title!=='string'||typeof r.fileHash!=='string'||!/^[0-9a-f]{64}$/.test(r.fileHash)||!Number.isInteger(r.n)||!Number.isFinite(Date.parse(r.approvedAt)))return null;return r}catch{return null}}
function verifyScreen(){const snapshot=parseRecord(),local=db.approvals.find(a=>a.id===(verifyId||snapshot?.id)),a=local?publicRecord(local):snapshot;if(!a)return `<header class="public-header"><div class="brand"><span class="mark">${icon('shield')}</span>HumanProof</div><button class="btn" data-action="workspace">작업 화면으로</button></header><main class="public-wrap"><section class="panel empty">${icon('info')}<h2>승인 기록을 찾을 수 없습니다</h2><p>승인 증명서를 발급한 뒤 검증 화면을 열어 주세요.</p></section></main>`;const revoked=!!a.revokedAt,old=local&&a.n!==current().n;return `<header class="public-header"><div class="brand"><span class="mark">${icon('shield')}</span>HumanProof <span class="small muted">승인 검증</span></div><div class="flex"><span class="demo-pill">수신자 화면 · 데모</span><button class="btn small" data-action="workspace">작업 화면으로</button></div></header><main class="public-wrap">${heading('승인 기록 확인','누가 승인했는지, 전달된 파일이 일치하는지 각각 확인합니다.')}<section class="panel"><div class="verify-status"><div class="status-symbol" style="${revoked?'background:#ffeff2;color:#c64557':!local?'background:#fff4e4;color:#b97c23':''}">${icon(revoked?'close':local?'shield':'info')}</div><div><div class="eyebrow">01 · APPROVAL STATUS</div><h2>${revoked?'승인이 철회되었습니다':!local?'발급 당시 승인 요약입니다':old?'v'+a.n+'의 승인 기록입니다':'승인 기록이 유효합니다'}</h2><p>${!local?'현재 효력은 조회할 수 없습니다. 이 링크의 요약은 전자서명되지 않았습니다.':old?'최신 버전 v'+current().n+'의 승인을 의미하지 않습니다.':'이 브라우저에 저장된 시연 기록 기준입니다.'}</p></div></div><div class="panel-body" style="border-top:1px solid var(--line)"><div class="detail-grid"><div class="detail-item"><span class="muted">승인된 작업</span>${esc(a.title)}</div><div class="detail-item"><span class="muted">승인 대상</span>v${a.n} · ${esc(a.fileName)}</div><div class="detail-item"><span class="muted">승인자</span>검토자 B</div><div class="detail-item"><span class="muted">승인 시각 (한국)</span>${stamp(a.approvedAt)}</div></div><div class="hash mt"><div><div class="small muted" style="margin-bottom:6px">승인 당시 SHA-256</div><div class="mono">${a.fileHash}</div></div></div>${revoked?`<div class="callout error mt"><div><b>철회 사유 · ${stamp(a.revokedAt)}</b>${esc(a.revocationReason)}</div></div>`:''}</div></section><section class="panel verify-upload"><div class="panel-head"><div><div class="eyebrow">02 · FILE INTEGRITY</div><h2>전달된 파일이 일치하나요?</h2></div><span class="badge">SHA-256 비교</span></div><div class="panel-body"><label class="dropzone" for="verifyFile">${icon('upload')}<b>확인할 PDF를 선택하세요</b><span class="small muted">20 MB 이하 · 파일 바이트의 해시를 비교합니다.</span><input id="verifyFile" type="file" accept="application/pdf,.pdf"></label><div class="flex wrap mt"><button class="btn small" data-action="compareOriginal" ${!local?'disabled':''}>원본 파일 비교</button><button class="btn small" data-action="compareTampered" ${!local?'disabled':''}>1바이트 변경 파일 비교</button>${local?'<button class="btn ghost small" data-action="downloadVerifyOriginal">원본 PDF 받기</button>':''}</div><div id="verifyResult">${verifyResultHtml()}</div><p class="inline-note">파일 비교는 이 기기에서 수행되며 파일을 서버로 전송하지 않습니다. 승인 기록의 상태와 파일 내용의 일치는 별개의 결과입니다.</p></div></section><p class="footer-note">발표용 프로토타입 · 다른 기기에서 열면 발급 당시 요약만 표시됩니다. 공개 검증 서버와 전자서명은 후속 구현 대상입니다. 비공개 과제 답변과 검토 메모는 이 화면에 포함하지 않습니다.</p></main>`}
function verifyResultHtml(){if(!verifyResult)return `<div class="result-box"><b>파일 미확인</b><p>파일을 선택해야 일치 여부를 알 수 있습니다.</p></div>`;if(verifyResult.error)return `<div class="result-box red">${esc(verifyResult.error)}</div>`;return `<div class="result-box ${verifyResult.match?'green':'red'}"><div class="flex"><b>${icon(verifyResult.match?'check':'close')} ${verifyResult.match?'파일이 일치합니다':'파일이 일치하지 않습니다'}</b></div><p>${verifyResult.match?'승인된 파일과 바이트가 동일합니다.':'전달된 파일은 승인된 파일과 다릅니다. 기존 승인이 이 파일에 적용되지 않습니다.'}</p><div class="small" style="margin-top:10px">${esc(verifyResult.fileName)}</div><div class="mono" style="margin-top:5px">${verifyResult.hash}</div></div>`}
function historyScreen(){return heading('버전 · 이력','파일 변경은 새 버전으로, 승인은 해당 버전의 기록으로 남습니다.',`<button class="btn primary" data-action="newVersion">${icon('plus')}새 버전 등록</button>`)+`<div class="split"><div><section class="panel gap"><div class="panel-head"><h2>파일 버전</h2><span class="small muted">${db.versions.length}개 버전</span></div>${[...db.versions].reverse().map(v=>`<div class="version-row"><div><div class="flex"><h3>v${v.n}</h3>${v.id===current().id?'<span class="badge purple">최신 버전</span>':''}${badge(v)}</div><p>${esc(v.fileName)} · ${stamp(v.createdAt)}</p><p>${esc(v.reason)}</p><div class="mono muted">${v.hash.slice(0,36)}…</div></div><button class="btn small" data-download-version="${v.id}">${icon('download')}파일</button></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>감사 타임라인</h2><button class="btn small" data-action="checkChain">${icon('link')}체인 확인</button></div><div id="chainResult"></div><div class="timeline">${[...db.events].reverse().map(e=>`<div class="event"><div class="event-icon">${icon(e.action.includes('승인')?'shield':e.action.includes('과제')?'brain':'file')}</div><div><h3>${esc(e.action)}</h3><p>${esc(e.actor)} · ${stamp(e.time)}</p><p>${esc(e.note)}</p><div class="mono">event_hash: ${e.eventHash.slice(0,26)}…</div></div></div>`).join('')}</div></section></div><aside class="support-column"><section class="guide"><div class="eyebrow">VERSION CONTROL</div><h2>변경되면 재승인이 필요합니다</h2><p>v1의 승인 뒤 v2를 등록해도 v1의 증명서는 남습니다. v2는 새 과제와 검토를 거쳐야 합니다.</p><button class="btn mt" data-nav="certificate">이전 승인 증명서 보기</button><p class="small">브라우저의 해시 체인은 시연 기록의 연결 여부를 확인합니다. 독립 감사 증명은 아닙니다.</p></section>${guide()}</aside></div>`}
function render(){if(!db)return;$('#app').innerHTML=screen==='verify'?verifyScreen():baseShell(({overview,gate:gateScreen,review:reviewScreen,certificate:certScreen,history:historyScreen}[screen]||overview)());if(screen==='certificate'&&latestApproval()&&typeof QRCode!=='undefined'){try{new QRCode($('#qrcode'),{text:verifyUrl(latestApproval()),width:176,height:176,colorDark:'#151b32',colorLight:'#fff',correctLevel:QRCode.CorrectLevel.L})}catch{$('#qrcode').textContent='검증 화면 버튼을 이용하세요';}}}
function navigate(s){screen=s;verifyResult=null;render();window.scrollTo({top:0,behavior:'instant'})}
function modal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="closeModal" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function riskFields(){return `<div class="form-row">${riskLabels.map((t,i)=>`<label class="field"><span>${t}</span><select name="risk${i}">${Array.from({length:riskMax[i]+1},(_,n)=>`<option value="${n}" ${n===[3,3,1,1][i]?'selected':''}>${n} / ${riskMax[i]}</option>`).join('')}</select></label>`).join('')}</div>`}
function registrationModal(isVersion=false){if(role!=='author'){toast('파일을 등록하려면 작성자 A로 전환하세요.');return}modal(isVersion?'새 버전 등록':'새 작업 등록',`<p>${isVersion?'이전 파일과 승인은 보존됩니다. 새 버전은 승인 전 상태로 시작합니다.':'현재 샘플 작업을 새 작업으로 바꿉니다. 시연용 작업은 한 번에 한 개를 체험합니다.'}</p><form id="registrationForm" data-version="${isVersion}">${!isVersion?'<label class="field"><span>작업 제목</span><input name="title" required maxlength="100" placeholder="예: AI 활용 프로젝트 보고서"></label>':''}<label class="field"><span>PDF 파일 · 최대 20 MB</span><input name="pdf" type="file" accept=".pdf,application/pdf"></label><label class="check-row"><input type="checkbox" name="useSample" checked>파일 없이 샘플 PDF로 시연하기</label>${isVersion?'<label class="field"><span>변경 사유</span><input name="reason" required value="검토 의견을 반영해 내용을 수정했습니다."></label>':''}<label class="field"><span>AI 활용 도구</span><input name="tool" required value="ChatGPT" maxlength="100"></label><label class="field"><span>AI 사용 범위 · 작성자 신고</span><textarea name="scope" required style="min-height:80px">설계 초안 생성 및 요구사항 정리</textarea></label><h3>위험 점수 입력</h3>${riskFields()}<p class="inline-note">검토자 B 배정 · 등록 후 세 종류의 이해 과제를 수행합니다.</p><div class="error-text" id="registrationError"></div><div class="modal-actions"><button type="button" class="btn" data-action="closeModal">취소</button><button type="submit" class="btn primary">${isVersion?'새 버전 등록':'등록 · 이해 과제 배정'}</button></div></form>`)}
async function validatePdf(file){if(file.size>20*1024*1024)throw Error('PDF는 20 MB 이하만 등록할 수 있습니다.');if(!/\.pdf$/i.test(file.name)||file.type&&file.type!=='application/pdf')throw Error('PDF 파일을 선택해 주세요.');const bytes=new Uint8Array(await file.arrayBuffer());const head=new TextDecoder().decode(bytes.subarray(0,5));if(head!=='%PDF-')throw Error('PDF 형식이 올바르지 않습니다. 확장자만 변경한 파일은 등록할 수 없습니다.');return bytes}
function ensureReviewer(){if(role!=='reviewer')throw Error('검토자 B 역할에서 진행하세요. 자기 승인은 금지됩니다.')}
function altered(bytes){const copy=new Uint8Array(bytes.length+1);copy.set(bytes);copy[copy.length-1]=10;return copy}
async function compare(bytes,fileName){const snap=parseRecord(),a=db.approvals.find(a=>a.id===(verifyId||snap?.id))||snap;if(!a)throw Error('승인 기록이 없습니다.');const h=await hash(bytes);verifyResult={match:h===(a.fileHash),hash:h,fileName};$('#verifyResult').innerHTML=verifyResultHtml()}
function activeVerifyApproval(){const snap=parseRecord();return db.approvals.find(a=>a.id===(verifyId||snap?.id))}
async function doAction(action,b){const v=current();switch(action){
 case 'sampleAnswer':if(role!=='author'||v.gates[gateIndex].submitted)return;v.gates[gateIndex].answer=samples[gateIndex];save();render();toast('샘플 답변을 채웠습니다. 내용을 확인하고 제출하세요.');break;
 case 'sampleAll':if(role!=='author')return;v.gates.forEach((g,i)=>{if(!g.submitted)g.answer=samples[i]});save();render();toast('각 과제 탭에서 답변 제출을 눌러 주세요.');break;
 case 'sampleEvaluation':ensureReviewer();if(!gatesSubmitted(v)||approvalFor(v))return;v.gates.forEach((g,i)=>g.evaluation={score:2,reason:['버전 식별과 바이트 무결성의 차이를 설명하고 재승인 조건을 확인했습니다.','파일명 비교의 오류를 발견하고 새 버전과 해시 비교를 제안했습니다.','승인 기록의 1:N 구조와 두 승인 완료 전 대기 상태를 설명했습니다.'][i],critical:false});v.memo='세 이해 과제의 설명과 판단 근거를 확인했습니다. 최종 PDF v'+v.n+'의 버전 ID와 해시, AI 사용 범위를 검토했습니다.';await audit('이해 과제 평가','검토자 B','세 과제 6 / 6점. 치명 오류 없음. 시연용 샘플 평가.');save();render();toast('평가를 채웠습니다. 체크리스트를 직접 확인하세요.');break;
 case 'approve':{ensureReviewer();const reasons=approvalReasons(v);if(reasons.length)throw Error(reasons[0]);const a={id:uid('receipt'),serial:'HP-2026-'+String(db.approvals.length+1).padStart(4,'0'),title:db.title,versionId:v.id,n:v.n,fileName:v.fileName,fileHash:v.hash,approvedAt:new Date().toISOString(),reviewer:'검토자 B',score:totalScore(v),memo:v.memo,aiDisclosureHash:await hashText(canonical({tool:v.tool,scope:v.scope})),checks:[...v.checks],evaluations:v.gates.map(g=>({...g.evaluation})),revokedAt:null};a.payload=JSON.parse(JSON.stringify(a));a.payloadHash=await hashText(canonical(a.payload));db.approvals.push(a);await audit('v'+v.n+' 인간 승인 · 증명서 발급','검토자 B','과제와 체크리스트를 확인하고 승인 대상을 '+v.id+'에 고정했습니다.');save();navigate('certificate');toast('v'+v.n+'의 승인 증명서를 발급했습니다.');break}
 case 'verify':{const a=db.approvals.find(a=>a.id===b?.dataset.id)||latestApproval();if(!a)throw Error('증명서를 먼저 발급해 주세요.');verifyId=a.id;verifyResult=null;location.hash=verifyUrl(a).split('#')[1];screen='verify';render();window.scrollTo(0,0);break}
 case 'workspace':history.replaceState(null,'',location.href.split('#')[0]);verifyId=null;verifyResult=null;navigate('overview');break;
 case 'compareOriginal':{const a=activeVerifyApproval();if(!a)throw Error('원본은 증명서를 발급한 브라우저에서만 비교할 수 있습니다.');const t=db.versions.find(v=>v.id===a.versionId);await compare(from64(t.fileData),t.fileName);break}
 case 'compareTampered':{const a=activeVerifyApproval();if(!a)throw Error('샘플 비교는 발급한 브라우저에서 진행하세요.');const t=db.versions.find(v=>v.id===a.versionId);await compare(altered(from64(t.fileData)),t.fileName.replace(/\.pdf$/i,'_1byte_changed.pdf'));break}
 case 'downloadOriginal':download(from64(v.fileData),v.fileName);break;
 case 'downloadVerifyOriginal':{const a=activeVerifyApproval(),t=db.versions.find(v=>v.id===a?.versionId);if(t)download(from64(t.fileData),t.fileName);break}
 case 'downloadReceipt':{const a=latestApproval();if(a)download(JSON.stringify({...a,signature:null,signatureStatus:'NOT_IMPLEMENTED_DEMO',demo:true},null,2),a.serial+'.json','application/json');break}
 case 'print':window.print();break;
 case 'newWork':registrationModal(false);break;
 case 'newVersion':registrationModal(true);break;
 case 'closeModal':closeModal();break;
 case 'reset':modal('시연을 처음부터 시작할까요?',`<p>이 브라우저의 시연 답변, 승인, 버전 이력을 지우고 최초 샘플 작업을 준비합니다.</p><div class="modal-actions"><button class="btn" data-action="closeModal">취소</button><button class="btn primary" data-action="confirmReset">초기화 · 시연 시작</button></div>`);break;
 case 'confirmReset':await seed();role='author';gateIndex=0;verifyId=null;history.replaceState(null,'',location.href.split('#')[0]);closeModal();navigate('overview');toast('처음부터 시연할 준비가 되었습니다.');break;
 case 'return':ensureReviewer();if(approvalFor(v))throw Error('승인된 버전에는 수정 요청을 할 수 없습니다.');modal('작성자에게 수정 요청',`<p>수정 사유를 기록하면 과제 답변을 다시 작성하고 제출할 수 있습니다.</p><form id="returnForm"><label class="field"><span>수정 요청 근거</span><textarea name="reason" required placeholder="어떤 답변을 어떻게 보완해야 하나요?"></textarea></label><div class="modal-actions"><button type="button" class="btn" data-action="closeModal">취소</button><button class="btn danger" type="submit">수정 요청 기록</button></div></form>`);break;
 case 'revoke':{ensureReviewer();const a=latestApproval();if(!a||a.revokedAt)return;modal('인간 승인 철회',`<p>철회 이후 검증 화면에 승인 철회 상태와 사유가 표시됩니다. 기존 기록은 남습니다.</p><form id="revokeForm"><label class="field"><span>공개할 철회 사유</span><textarea name="reason" required placeholder="예: 승인 후 근거 자료의 오류를 발견했습니다."></textarea></label><div class="modal-actions"><button class="btn" type="button" data-action="closeModal">취소</button><button class="btn danger" type="submit">승인 철회 기록</button></div></form>`);break}
 case 'checkChain':{let prev='0'.repeat(64),ok=true;for(const e of db.events){const body={id:e.id,action:e.action,actor:e.actor,note:e.note,target:e.target,time:e.time};if(e.prevHash!==prev||e.eventHash!==await hashText(prev+canonical(body))){ok=false;break}prev=e.eventHash}$('#chainResult').innerHTML=`<div class="callout ${ok?'success':'error'}" style="margin:20px"><div><b>${ok?'해시 체인 연결 확인':'해시 체인 불일치'}</b>${db.events.length}개 이벤트 ${ok?'연결이 일치합니다.':'중 변경되거나 누락된 기록이 있습니다.'}<br><span class="small">브라우저 시연 기록이며 독립적인 감사 인증은 아닙니다.</span></div></div>`;break}
 }}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}const tab=e.target.closest('[data-gate]');if(tab){gateIndex=Number(tab.dataset.gate);render();return}const dl=e.target.closest('[data-download-version]');if(dl){const v=db.versions.find(v=>v.id===dl.dataset.downloadVersion);if(v)download(from64(v.fileData),v.fileName);return}const b=e.target.closest('[data-action]');if(!b||b.disabled||busy)return;busy=true;try{await doAction(b.dataset.action,b)}catch(err){toast(err.message||'다시 시도해 주세요.')}finally{busy=false}});
document.addEventListener('input',e=>{if(!db)return;const v=current(),g=v.gates[gateIndex];if(e.target.id==='answer'&&role==='author'&&!g.submitted){g.answer=e.target.value;save()}if(e.target.id==='confidence'&&role==='author'&&!g.submitted){g.confidence=Number(e.target.value);$('#confidenceValue').textContent=g.confidence+'%';save()}const index=e.target.dataset.evalReason;if(index!==undefined&&role==='reviewer'&&!approvalFor(v)&&v.gates[index]?.submitted){const a=v.gates[index];a.evaluation??={score:0,reason:'',critical:false};a.evaluation.reason=e.target.value;save();$('#approvalControls').innerHTML=approvalControls()}if(e.target.id==='reviewMemo'&&role==='reviewer'&&!approvalFor(v)){v.memo=e.target.value;save();$('#approvalControls').innerHTML=approvalControls()}});
document.addEventListener('change',async e=>{if(!db)return;const v=current();if(e.target.id==='role'){role=e.target.value==='reviewer'?'reviewer':'author';render();toast(role==='reviewer'?'검토자 B로 전환했습니다.':'작성자 A로 전환했습니다.');return}if(e.target.id==='verifyFile'){try{const f=e.target.files[0];if(f)await compare(await validatePdf(f),f.name)}catch(err){verifyResult={error:err.message};$('#verifyResult').innerHTML=verifyResultHtml()}return}if(role!=='reviewer'||approvalFor(v))return;const i=e.target.dataset.evalScore,j=e.target.dataset.critical,k=e.target.dataset.check;if(i!==undefined&&v.gates[i].submitted){v.gates[i].evaluation??={score:0,reason:'',critical:false};v.gates[i].evaluation.score=Number(e.target.value);save();render()}if(j!==undefined&&v.gates[j].submitted){v.gates[j].evaluation??={score:0,reason:'',critical:false};v.gates[j].evaluation.critical=e.target.checked;save();render()}if(k!==undefined){v.checks[k]=e.target.checked;save();$('#approvalControls').innerHTML=approvalControls()}});
document.addEventListener('submit',async e=>{if(!['gateForm','registrationForm','revokeForm','returnForm'].includes(e.target.id))return;e.preventDefault();if(busy)return;busy=true;const f=e.target;try{
 if(f.id==='gateForm'){const v=current(),g=v.gates[gateIndex];if(role!=='author'||g.submitted)return;g.answer=$('#answer').value.trim();if(!g.answer){$('#gateError').textContent='답변을 입력해 주세요.';return}g.submitted=true;g.evaluation=null;v.returned=false;await audit(gateNames[gateIndex]+' 답변 제출','작성자 A','자기 확신 '+g.confidence+'%. 답변을 이 파일 버전의 과제에 연결했습니다.');save();if(gateIndex<2)gateIndex++;render();toast(gatesSubmitted(v)?'세 과제가 제출되었습니다. 검토자 B로 전환하세요.':'답변을 제출했습니다. 다음 과제를 확인하세요.');}
 if(f.id==='registrationForm'){const form=new FormData(f),isVersion=f.dataset.version==='true';if(role!=='author')throw Error('작성자 역할에서만 등록할 수 있습니다.');let bytes,name;const file=form.get('pdf');if(file?.size){bytes=await validatePdf(file);name=file.name}else if(form.get('useSample')){bytes=isVersion?altered(from64(current().fileData)):makePdf();name=isVersion?'system_design_v'+(current().n+1)+'.pdf':'system_design_v1.pdf'}else throw Error('PDF를 선택하거나 샘플 PDF를 선택하세요.');const title=isVersion?db.title:String(form.get('title')).trim(),tool=String(form.get('tool')).trim(),scope=String(form.get('scope')).trim(),reason=isVersion?String(form.get('reason')).trim():'최초 파일 등록';if(!title||!tool||!scope||!reason)throw Error('필수 항목을 모두 입력해 주세요.');const risk=riskLabels.map((_,i)=>Number(form.get('risk'+i)));if(risk.some((n,i)=>!Number.isInteger(n)||n<0||n>riskMax[i]))throw Error('위험 점수가 올바르지 않습니다.');const n=isVersion?current().n+1:1,version=await makeVersion(n,name,bytes,tool,scope,risk,reason);if(isVersion){if(version.hash===current().hash&&tool===current().tool&&scope===current().scope)throw Error('파일과 AI 신고가 같습니다. 변경된 파일을 선택해 주세요.');db.versions.push(version)}else db={schema:2,workId:uid('work'),title,versions:[version],approvals:[],events:[]};await audit('PDF v'+n+' 등록 · 과제 배정','작성자 A',reason+(isVersion?' 이전 버전의 승인은 새 버전에 적용되지 않습니다.':''));save();gateIndex=0;closeModal();navigate('overview');toast('v'+n+' 버전을 등록했습니다. 이해 과제를 시작하세요.');}
 if(f.id==='revokeForm'){ensureReviewer();const reason=String(new FormData(f).get('reason')).trim();if(!reason)throw Error('철회 사유를 입력해 주세요.');const a=latestApproval();if(!a||a.revokedAt)throw Error('철회할 승인이 없습니다.');a.revokedAt=new Date().toISOString();a.revocationReason=reason;await audit('v'+a.n+' 승인 철회','검토자 B',reason,a.versionId);save();closeModal();navigate('certificate');toast('승인이 철회되었습니다. 검증 화면에서도 확인할 수 있습니다.');}
 if(f.id==='returnForm'){ensureReviewer();const reason=String(new FormData(f).get('reason')).trim(),v=current();if(!reason)throw Error('수정 요청 근거를 입력해 주세요.');if(approvalFor(v))throw Error('승인된 버전에는 수정 요청을 할 수 없습니다.');v.gates.forEach(g=>g.submitted=false);v.returned=true;v.checks=checks.map(()=>false);await audit('과제 수정 요청','검토자 B',reason);save();closeModal();navigate('gate');toast('작성자 A로 전환해 답변을 보완해 주세요.');}
 }catch(err){const target=f.id==='registrationForm'?$('#registrationError'):f.id==='gateForm'?$('#gateError'):null;if(target)target.textContent=err.message;else toast(err.message)}finally{busy=false}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#verify=')){screen='verify';verifyResult=null;render()}else if(screen==='verify')navigate('overview')});
window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.schema===2){db=next;render()}}catch{}}});
async function init(){try{if(!crypto.subtle)throw Error('파일 해시 계산을 위해 로컬 서버 또는 HTTPS 주소로 열어 주세요.');try{const cached=JSON.parse(localStorage.getItem(STORAGE)||'null');if(cached?.schema===2&&cached.versions?.length&&Array.isArray(cached.events)&&Array.isArray(cached.approvals))db=cached}catch{}if(!db)await seed();if(location.hash.startsWith('#verify='))screen='verify';render();registerAgentTools()}catch(err){$('#app').innerHTML=`<main class="public-wrap"><section class="panel empty"><h1>프로토타입을 열 수 없습니다</h1><p>${esc(err.message)}</p><button class="btn primary" onclick="localStorage.removeItem('${STORAGE}');location.reload()">시연 저장소 초기화</button></section></main>`}}
function registerAgentTools(){if(!document.modelContext?.registerTool)return;const ctl=new AbortController();window.addEventListener('pagehide',()=>ctl.abort(),{once:true});const specs=[{name:'read_demo_work_status',title:'시연 작업 상태 조회',description:'현재 시연 작업의 버전, 과제 제출 상태, 승인 상태를 조회합니다. 비공개 답변은 반환하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('빈 객체를 전달하세요.');const v=current();return {version:v.n,status:statusOf(v)[0],submitted:v.gates.filter(g=>g.submitted).length,approvalAvailable:!!approvalFor(v)}}},{name:'navigate_demo_workflow',title:'시연 화면 이동',description:'HumanProof의 기존 화면으로 이동합니다. 답변 제출 또는 승인은 실행하지 않습니다.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['overview','gate','review','certificate','history']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['overview','gate','review','certificate','history'].includes(input.screen))throw Error('올바른 screen을 전달하세요.');if(location.hash.startsWith('#verify='))history.replaceState(null,'',location.href.split('#')[0]);navigate(input.screen);return{screen}}}];for(const spec of specs){try{Promise.resolve(document.modelContext.registerTool(spec,{signal:ctl.signal})).catch(()=>{})}catch{}}}
init();
